import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def get_lcm_list(arr):
    if not arr:
        return []
    lcm_list = [arr[0]]
    for i in range(1, len(arr)):
        lcm_list.append(lcm(lcm_list[-1], arr[i]))
    return lcm_list

def get_gcd_list(arr):
    if not arr:
        return []
    gcd_list = [arr[-1]]
    for i in range(len(arr)-2, -1, -1):
        gcd_list.append(gcd(gcd_list[-1], arr[i]))
    return gcd_list[::-1]

def count_good_partitions(a):
    n = len(a)
    if n < 2:
        return 0

    lcm_vals = []
    current_lcm = a[0]
    for k in range(1, n):
        lcm_vals.append(current_lcm)
        current_lcm = lcm(current_lcm, a[k])

    # Wait, the definition says A_k = {a_1, ..., a_k} and B_k = {a_{k+1}, ..., a_n}
    # k goes from 1 to n-1.
    # A_1 = {a_1}, B_1 = {a_2, ..., a_n}
    # A_2 = {a_1, a_2}, B_2 = {a_3, ..., a_n}
    # ...
    # A_{n-1} = {a_1, ..., a_{n-1}}, B_{n-1} = {a_n}

    # Re-calculating L_k and G_k
    L = [0] * (n) # L[k] will be lcm(a_1, ..., a_k)
    G = [0] * (n+1) # G[k] will be gcd(a_{k+1}, ..., a_n)

    curr_lcm = a[0]
    for k in range(1, n):
        L[k] = curr_lcm
        curr_lcm = lcm(curr_lcm, a[k])

    curr_gcd = a[n-1]
    G[n-1] = curr_gcd
    for k in range(n-2, 0, -1):
        curr_gcd = gcd(curr_gcd, a[k])
        G[k] = curr_gcd
    # Wait, G_k is gcd(a_{k+1}, ..., a_n).
    # If k=1, G_1 = gcd(a_2, ..., a_n).
    # If k=n-1, G_{n-1} = gcd(a_n) = a_n.

    # Let's do it properly.
    L = [0] * (n + 1)
    for k in range(1, n):
        if k == 1:
            L[k] = a[0]
        else:
            L[k] = lcm(L[k-1], a[k-1])

    G = [0] * (n + 1)
    for k in range(n-1, 0, -1):
        if k == n-1:
            G[k] = a[n-1]
        else:
            # G[k] = gcd(a_{k+1}, ..., a_n)
            # No, G[k] = gcd(a_{k+1}, ..., a_n). Let's use index k.
            # a is 0-indexed. a_1 is a[0], a_n is a[n-1].
            # A_k = {a[0], ..., a[k-1]}, B_k = {a[k], ..., a[n-1]}
            pass

    # Let's restart.
    count = 0
    for k in range(1, n):
        # A_k = a[0:k], B_k = a[k:n]
        ak = a[0:k]
        bk = a[k:n]

        l_k = ak[0]
        for i in range(1, len(ak)):
            l_k = lcm(l_k, ak[i])

        g_k = bk[0]
        for i in range(1, len(bk)):
            g_k = gcd(g_k, bk[i])

        if l_k == g_k:
            count += 1
    return count

